describe('API Response Caching', () => {
    beforeEach(() => {
        cy.intercept('GET', '/api/data', (req) => {
            req.reply((res) => {
                res.send({
                    statusCode: 200,
                    body: { data: 'cached response' },
                    headers: { 'Cache-Control': 'max-age=3600' }
                });
            });
        }).as('getData');
    });

    it('should return cached response on first visit', () => {
        cy.visit('/data-page');
        cy.wait('@getData').its('response.statusCode').should('eq', 200);
        cy.get('.data-display').should('contain', 'cached response');
    });

    it('should return cached response on repeat visit', () => {
        cy.visit('/data-page');
        cy.wait('@getData');
        cy.reload();
        cy.wait('@getData').its('response.statusCode').should('eq', 200);
        cy.get('.data-display').should('contain', 'cached response');
    });
});
